<?php
namespace Modules\Glitter\Analytics\Services;
use Carbon\CarbonImmutable; use Illuminate\Pagination\LengthAwarePaginator; use Modules\Glitter\Analytics\DTO\AnalyticsVisitFilter; use Modules\Glitter\Analytics\Repositories\Contracts\AnalyticsEventRepositoryInterface;
class AnalyticsQueryService {
 public function __construct(private AnalyticsEventRepositoryInterface $events){}
 public function filter(array $input,?CarbonImmutable $now=null):AnalyticsVisitFilter{$tz=(string)config('app.default_user_timezone','Asia/Seoul');$now=($now??CarbonImmutable::now($tz))->setTimezone($tz);$toDate=(string)($input['to']??$now->format('Y-m-d'));$fromDate=(string)($input['from']??$now->subDays(6)->format('Y-m-d'));$from=CarbonImmutable::createFromFormat('!Y-m-d',$fromDate,$tz)->utc();$to=CarbonImmutable::createFromFormat('!Y-m-d',$toDate,$tz)->addDay()->utc();return new AnalyticsVisitFilter($from,$to,$fromDate,$toDate,$tz,isset($input['path'])&&trim((string)$input['path'])!==''?trim((string)$input['path']):null,$input['source']??null,$input['member']??'all',(int)($input['page']??1),(int)($input['per_page']??20));}
 public function visits(array $input):LengthAwarePaginator{return $this->events->paginateVisits($this->filter($input));}
 public function export(array $input):\Illuminate\Support\LazyCollection{return $this->events->cursorVisits($this->filter($input));}
 public function dashboard(?CarbonImmutable $now=null):array{$tz=(string)config('app.default_user_timezone','Asia/Seoul');$now=($now??CarbonImmutable::now($tz))->setTimezone($tz);$input=['from'=>$now->subDays(6)->format('Y-m-d'),'to'=>$now->format('Y-m-d'),'per_page'=>20];$filter=$this->filter($input,$now);$today=CarbonImmutable::createFromFormat('!Y-m-d',$now->format('Y-m-d'),$tz)->utc();$days=[];for($i=6;$i>=0;$i--){$date=$now->subDays($i)->format('Y-m-d');$from=CarbonImmutable::createFromFormat('!Y-m-d',$date,$tz);$days[]=['date'=>$date,'from'=>$from->utc(),'to'=>$from->addDay()->utc()];}$host=parse_url((string)config('app.url'),PHP_URL_HOST);return ['timezone'=>$tz,'summary'=>$this->events->summary($filter,$today),'trend'=>$this->events->dailyTrend($days),'popular_paths'=>$this->events->popularPaths($filter,10),'referrers'=>$this->events->topReferrers($filter,10,is_string($host)?$host:null),'recent_visits'=>$this->events->recentVisits($filter,10)];}
}
